  -- Pollo al jugo con arroz
  v_v := pg_temp.receta('Pollo al jugo con arroz', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 40, 'Pechuga cocida lento en su propio jugo con cebolla, sobre arroz blanco. Rápida y liviana.');
