  -- Pollo al horno con papas
  v_v := pg_temp.receta('Pollo al horno con papas', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 70, 'Trutros y papas en la misma fuente, con ajo, orégano y limón. Se arma en diez minutos y el horno hace el resto.');
  s := pg_temp.slot(v_v, 'PROTEIN', 1, null, true);
  perform pg_temp.comp(s, 'pollo trutro entero con piel', 'RAW', 900, 'G', 'BAKED', false, 1, null, 'MAIN', 'ADJUSTABLE', 700, 1200, null, null, null);
  s := pg_temp.slot(v_v, 'CARBOHYDRATE', 2, null, true);
  perform pg_temp.comp(s, 'papa', 'RAW', 800, 'G', 'BAKED', false, 1, null, 'MAIN', 'ADJUSTABLE', 500, 1000, null, null, null);
