  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 5, 'G', null, false, 4, null, 'SEASONING', 'ADJUSTABLE', 0, 6, null, null, null);
  s := pg_temp.slot(v_v, 'FAT', 5, null, true);
  perform pg_temp.comp(s, 'aceite vegetal', 'AS_PACKAGED', 25, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 10, 30, null, null, null);
  perform pg_temp.paso(v_v, 1, 'Precalentar el horno.', 10, 200, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Aliñar los trutros con ajo molido, orégano, jugo de limón, sal y la mitad del aceite.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Poner las papas en rodajas y la cebolla en el fondo de la fuente con el resto del aceite; encima el pollo con la piel hacia arriba.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Hornear hasta que la piel esté dorada y el jugo del muslo salga claro al pincharlo.', 55, 200, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Para el dorado final: si el horno tiene calor solo por arriba, usarlo los últimos minutos; si no, subirlo al máximo con la fuente en la rejilla de más arriba.', 6, null, null, null, null);
