  -- Caldo de pollo casero
  v_v := pg_temp.receta('Caldo de pollo casero', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 95, 'Trutros hervidos muy suave con cebolla, zanahoria, apio y perejil hasta sacarles todo el sabor. Es la receta base que hace que una olla rinda tres comidas: de acá salen las pantrucas, el ajiaco y la sopa de fideos.');
  s := pg_temp.slot(v_v, 'PROTEIN', 1, null, true);
  perform pg_temp.comp(s, 'pollo trutro entero con piel', 'RAW', 1000, 'G', 'BOILED', false, 1, null, 'MAIN', 'ADJUSTABLE', 800, 1400, 'peso con hueso y piel: el sabor del caldo sale del hueso, así que las presas van enteras y sin deshuesar', null, null);
  perform pg_temp.alt(s, 'pechuga de pollo sin piel', 'ACCEPTABLE', 'rinde más carne, pero el caldo queda flaco y sin cuerpo: lo que gelatiniza el caldo es el hueso y el cartílago del trutro', 0.7);
  s := pg_temp.slot(v_v, 'VEGETABLE', 2, null, true);
  perform pg_temp.comp(s, 'cebolla', 'RAW', 200, 'G', 'BOILED', false, 1, null, 'MAIN', 'ADJUSTABLE', 150, 300, 'partida en mitades, no picada: picada enturbia el caldo', null, null);
  perform pg_temp.comp(s, 'zanahoria', 'RAW', 200, 'G', 'BOILED', false, 2, null, 'MAIN', 'ADJUSTABLE', 150, 300, null, null, null);
  perform pg_temp.comp(s, 'apio', 'RAW', 100, 'G', 'BOILED', false, 3, null, 'MAIN', 'ADJUSTABLE', 60, 150, 'tallos en trozos grandes; sirven también las hojas, que perfuman más que el tallo', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 3, null, true);
  perform pg_temp.comp(s, 'perejil fresco', 'RAW', 15, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', 5, 20, 'los tallos van al caldo desde el principio y dan más sabor que las hojas', null, null);
  perform pg_temp.comp(s, 'ajo', 'RAW', 8, 'G', null, true, 2, null, 'SEASONING', 'OPTIONAL', null, null, 'dientes enteros aplastados, con piel y todo', null, null);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 6, 'G', null, false, 3, null, 'SEASONING', 'ADJUSTABLE', 0, 8, 'va recién al final. Si el caldo se va a usar como base de otra receta que además se reduce, conviene salar menos todavía o no salar.', null, null);
  perform pg_temp.alt(s, 'cilantro', 'GOOD', 'cambia el perfume del caldo por completo; el perejil es lo neutro y sirve para cualquier cosa que se cocine después con esta base', 1);
  perform pg_temp.paso(v_v, 1, 'Pon las presas en la olla y cúbrelas con agua fría, unos tres litros. Llévalas a hervor lento y destapadas: el agua fría de partida es la que saca el sabor hacia el caldo.', 15, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Saca con espumadera la espuma gris que sube los primeros minutos. Es lo único que enturbia el caldo y después ya no se puede arreglar.', 5, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Agrega la cebolla en mitades, la zanahoria, el apio, los tallos de perejil y el ajo aplastado. Deja hervir apenas temblando, con la olla semitapada: si burbujea fuerte el caldo se pone turbio y no queda más claro después.', 60, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'En vez de la olla común: cierra la olla a presión con los mismos ingredientes y cuenta el tiempo desde que toma presión.', 30, null, 'PRESSURE_COOKER', 'Sin olla a presión: son los 60 minutos de hervor suave de la olla normal. Subir el fuego no acorta nada y solo deja el caldo turbio.', null);
  perform pg_temp.paso(v_v, 5, 'Cuela el caldo apretando poco las verduras. Saca la carne del hueso apenas se pueda tomar con la mano y deshuésala y desmenúzala mientras el caldo se cuela.', 10, null, null, null, null);
  perform pg_temp.paso(v_v, 6, 'Prueba y sala recién ahora, cuando el caldo ya se concentró. Agrega las hojas de perejil picadas al servir.', 2, null, null, null, null);
  perform pg_temp.paso(v_v, 7, 'Devuelve la carne desmenuzada al caldo colado y calienta un minuto antes de servir. Si la vas a guardar para otra preparación, sirve el caldo solo y anota que ese plato ya no lleva la proteína.', 2, null, null, null, null);
  perform pg_temp.publicar(v_v);

