  perform pg_temp.comp(s, 'aceite vegetal', 'AS_PACKAGED', 25, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 15, 30, 'la mitad para el pollo y la mitad para la verdura; el salteado necesita sarten seca y caliente, no bañada en aceite', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 5, null, true);
  perform pg_temp.comp(s, 'ajo', 'RAW', 6, 'G', null, true, 1, null, 'SEASONING', 'OPTIONAL', null, null, null, null, null);
