  perform pg_temp.comp_anidada(s, 'Ensalada chilena', 1, 1);
  perform pg_temp.paso(v_v, 1, 'Muele el ajo con la sal, mezclalo con el oregano, el comino, el jugo de medio limon y el aceite, y unta las presas por todos lados, tambien por debajo de la piel. Dejalas tomar el adobo mientras preparas el resto.', 15, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Sin parrilla el pollo sale igual de bien: pon las presas con la piel hacia arriba en una fuente y asalas en el horno hasta que la piel este dorada y el jugo salga claro al picar el muslo hasta el hueso.', 45, 200, null, null, 1);
  perform pg_temp.paso(v_v, 3, 'En vez del horno: pon las presas en la parrilla cuando las brasas ya esten blancas, primero con la piel hacia arriba y al calor indirecto, dandoles vuelta cada 10 minutos. Recien al final las pasas sobre las brasas, con la piel abajo, para dorar.', 40, null, 'GRILL', 'Sin parrilla: el horno a 200 grados del paso anterior es el metodo base de esta receta.', null);
  perform pg_temp.paso(v_v, 4, 'Mientras el pollo se asa, arma la ensalada chilena.', 12, null, null, null, 1);
  perform pg_temp.paso(v_v, 5, 'Deja reposar las presas unos minutos antes de partirlas: si las abres al tiro, el jugo se va entero a la tabla. Sirve con la ensalada y el resto del limon para exprimir encima.', 5, null, null, null, null);
