  perform pg_temp.comp(s, 'cebolla', 'RAW', 100, 'G', 'RAW', false, 3, null, 'MAIN', 'ADJUSTABLE', 60, 150, 'en pluma bien fina; cortada gruesa se come sola y tapa la albahaca', null, null);
  perform pg_temp.alt(s, 'pimiento rojo', 'GOOD', 'en cubos chicos junto al tomate; suma color y crujido sin soltar agua', 0.5);
