  perform pg_temp.comp(s, 'albahaca fresca', 'RAW', 15, 'G', 'RAW', false, 1, null, 'SEASONING', 'ADJUSTABLE', 8, 25, 'es la que le da el nombre al plato, no un adorno: si no hay albahaca, esto es otra ensalada', null, null);
  perform pg_temp.comp(s, 'limon', 'RAW', 40, 'G', null, false, 2, null, 'SEASONING', 'ADJUSTABLE', 20, 60, 'acá el limón es aliño: se usa el jugo', null, null);
