  perform pg_temp.alt(s, 'perejil fresco', 'ACCEPTABLE', 'cuando no se consigue albahaca; el plato cambia de carácter y deja de ser el de verano', 1);
  s := pg_temp.slot(v_v, 'FAT', 3, null, true);
  perform pg_temp.comp(s, 'aceite de oliva', 'AS_PACKAGED', 30, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 15, 40, null, null, null);
  perform pg_temp.paso(v_v, 1, 'Cuece los granos de choclo en agua hirviendo hasta que estén tiernos pero firmes, escúrrelos y enfríalos bajo el chorro para cortarles la cocción.', 12, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Corta la cebolla en pluma fina y déjala unos minutos en agua fría para quitarle el filo; después escúrrela bien apretándola con la mano.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Corta el tomate en cubos y déjalo escurriendo en un colador: el agua del tomate es lo que aguacha esta ensalada.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Junta el choclo frío, el tomate escurrido y la cebolla, y alíñalos con el aceite de oliva, el jugo de limón y la sal.', 4, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Corta la albahaca con la mano justo antes de servir y revuélvela por encima. Picada con cuchillo y con anticipación se pone negra.', 2, null, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Sopa de pollo con fideos
  v_v := pg_temp.receta('Sopa de pollo con fideos', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 85, 'Caldo de trutro colado, con la verdura picada chica, el pollo desmenuzado y fideo fino cocido al final. Es la sopa del resfriado y del día helado: no lleva papa entera ni zapallo, y eso es justamente lo que la separa de la cazuela.');
