  -- Leche asada
  v_v := pg_temp.receta('Leche asada', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 80, 'Leche, huevo y azúcar cuajados al horno sobre un fondo de caramelo, con canela. Es el postre de domingo que sale entero con lo que ya hay en la casa, sin comprar nada especial, y alcanza para toda la mesa.');
