  perform pg_temp.paso(v_v, 2, 'Seca bien las alitas con papel y aliñalas con el ajo molido, el orégano, el ají de color, el jugo de medio limón, la sal y la mitad del aceite. Revuélvelas con las manos para que el aliño llegue por todos lados y déjalas tomando gusto.', 12, null, null, null, 1);
  perform pg_temp.paso(v_v, 3, 'Corta las papas en rodajas parejas y extiéndelas en una sola capa en la fuente con el resto del aceite y una pizca de sal.', 8, null, null, null, null);
