  -- Asado de tira a la parrilla con ensalada chilena
  v_v := pg_temp.receta('Asado de tira a la parrilla con ensalada chilena', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 70, 'Tiras de costilla asadas lento, con sal gruesa y nada más, servidas con ensalada chilena y pebre. Es el domingo chileno completo: la carne manda y el resto está ahí para acompañarla.');
