  -- Porotos con mazamorra
  v_v := pg_temp.receta('Porotos con mazamorra', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 85, 'Porotos granados de verano cocidos con zapallo hasta que se deshace, espesados con choclo molido y perfumados con albahaca al final. La mazamorra es justamente eso: el choclo raspado de la coronta y molido a pasta, que es lo que le da cuerpo a la olla en vez de andar flotando en granos enteros.');
  s := pg_temp.slot(v_v, 'PROTEIN', 1, null, true);
