  perform pg_temp.alt(s, 'porotos secos', 'ACCEPTABLE', 'fuera de temporada se hace con poroto seco remojado desde la noche anterior, pero deja de ser el poroto granado de verano: el grano queda mucho más firme y la olla, más pesada', 0.4);
  s := pg_temp.slot(v_v, 'CARBOHYDRATE', 2, null, true);
