  perform pg_temp.alt(s, 'choclo en grano', 'GOOD', 'el choclo en grano congelado se muele igual y te ahorra raspar las coronas; el peso baja a un tercio porque ya viene sin coronta, y la mazamorra queda menos dulce', 0.33);
  s := pg_temp.slot(v_v, 'VEGETABLE', 3, null, true);
