  perform pg_temp.comp(s, 'cebolla', 'RAW', 200, 'G', 'STEWED', false, 2, null, 'MAIN', 'ADJUSTABLE', null, null, null, null, null);
  s := pg_temp.slot(v_v, 'FAT', 4, null, true);
