  perform pg_temp.comp(s, 'albahaca fresca', 'RAW', 20, 'G', 'RAW', false, 1, null, 'SEASONING', 'ADJUSTABLE', 10, 30, 'entra picada con el fuego ya apagado; hervida pierde todo el perfume, que es lo único que aporta', null, null);
  perform pg_temp.comp(s, 'ajo', 'RAW', 8, 'G', null, true, 2, null, 'SEASONING', 'OPTIONAL', 0, 12, null, null, null);
