  -- Ensalada de porotos con cebolla y huevo
  v_v := pg_temp.receta('Ensalada de porotos con cebolla y huevo', 'SALAD', array['LUNCH', 'DINNER']::public.meal_type[], 4, 110, 'Porotos cocidos y bien fríos con cebolla en pluma curada en limón, huevo duro en gajos y un aliño de aceite de oliva y perejil. Es la forma chilena de aprovechar la olla de porotos que sobró: se come fría en verano y se sostiene sola como almuerzo, sin necesitar carne.');
  s := pg_temp.slot(v_v, 'PROTEIN', 1, null, true);
