  perform pg_temp.comp(s, 'huevo de gallina', 'EDIBLE_PORTION', 220, 'G', 'BOILED', false, 2, null, 'MAIN', 'ADJUSTABLE', 110, 330, 'duros, en gajos encima; son la otra mitad de la proteína del plato', 'unidad', 4);
  perform pg_temp.alt(s, 'lentejas', 'GOOD', 'la lenteja no necesita remojo y se cuece en mucho menos rato, pero se deshace más fácil: sácala del fuego apenas ceda o la ensalada queda pastosa', 1);
