  perform pg_temp.alt(s, 'tomate', 'GOOD', 'en gajos sumados al final; suelta harta agua, así que se alíña justo antes de llevarlo a la mesa', null);
  s := pg_temp.slot(v_v, 'FAT', 3, null, true);
  perform pg_temp.comp(s, 'aceite de oliva', 'AS_PACKAGED', 40, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 20, 50, 'todo crudo en el aliño: acá no se pierde nada en la sartén', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 4, null, true);
  perform pg_temp.comp(s, 'limon', 'RAW', 60, 'G', 'RAW', false, 1, null, 'SEASONING', 'ADJUSTABLE', 40, 90, null, null, null);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 4, 'G', null, false, 2, null, 'SEASONING', 'ADJUSTABLE', 0, 6, 'nada de sal en el agua de cocción; la sal va toda en el aliño, al final', null, null);
  s := pg_temp.slot(v_v, 'TOPPING', 5, null, false);
