  v_v := pg_temp.receta('Sopaipillas pasadas', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 40, 'Sopaipillas ya fritas ahogadas en almíbar caliente de chancaca con canela y limón. Es el postre del día de lluvia y la mejor manera de aprovechar las sopaipillas que quedaron.');
  s := pg_temp.slot(v_v, 'SWEETENER', 1, null, true);
