  v_v := pg_temp.receta('Mote con huesillo', 'DESSERT', array['DESSERT', 'SNACK', 'TEA']::public.meal_type[], 6, 55, 'Duraznos deshidratados cocidos en jugo de chancaca con canela, servidos bien fríos sobre mote de trigo. Se toma con cuchara y llena como comida; en casa sale por una fracción de lo que cuesta en la calle.');
