  perform pg_temp.comp(s, 'chancaca', 'AS_PACKAGED', 150, 'G', 'BOILED', false, 1, null, 'MAIN', 'ADJUSTABLE', 100, 200, 'es lo que le da el color y el sabor al jugo; sin ella queda un agua de durazno pálida', null, null);
