  s := pg_temp.slot(v_v, 'BASE', 2, null, true);
  perform pg_temp.comp(s, 'harina de trigo', 'RAW', 290, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 250, 330, '250 g para la masa de la tapa y 40 g para ligar la salsa blanca', null, null);
