  s := pg_temp.slot(v_v, 'VEGETABLE', 4, null, true);
  perform pg_temp.comp(s, 'cebolla', 'RAW', 200, 'G', 'STEWED', false, 1, null, 'MAIN', 'ADJUSTABLE', null, null, null, null, null);
