  perform pg_temp.comp(s, 'choclo en grano', 'RAW', 200, 'G', 'STEWED', false, 4, null, 'MAIN', 'ADJUSTABLE', null, null, null, null, null);
  perform pg_temp.alt(s, 'poroto verde', 'GOOD', 'picado corto, en vez de las arvejas; hay que blanquearlo antes o queda crudo dentro del pie', null);
