  perform pg_temp.paso(v_v, 1, 'Cuece la pechuga en tiras en agua apenas salada, a fuego suave, hasta que ceda. Sácala, déjala entibiar y desmenúzala con dos tenedores. Guarda una taza del caldo.', 15, null, null, null, 1);
  perform pg_temp.paso(v_v, 2, 'Mientras el pollo se cuece, arena los 250 g de harina de la masa con la mantequilla fría entre los dedos hasta que quede como migas; agrega un huevo y agua helada de a cucharadas, junta sin amasar y deja la masa tapada en frío.', 15, null, null, null, 1);
  perform pg_temp.paso(v_v, 3, 'Precalienta el horno.', 10, 200, null, null, 2);
  perform pg_temp.paso(v_v, 4, 'Sofríe la cebolla, la zanahoria y las arvejas con la mantequilla que quedó, hasta que la cebolla esté transparente.', 8, null, null, null, 2);
  perform pg_temp.paso(v_v, 5, 'Espolvorea la harina reservada, revuelve un minuto para que pierda el gusto a crudo y agrega la leche caliente de a poco, batiendo, hasta que espese.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 6, 'Suma el pollo desmenuzado y el choclo, sala y ajusta con el caldo hasta que quede cremoso y no líquido. Déjalo entibiar antes de taparlo: si va hirviendo, la masa se derrite encima.', 4, null, null, null, null);
  perform pg_temp.paso(v_v, 7, 'Vierte el relleno en la fuente, estira la masa, tápala, sella los bordes, hazle dos cortes al medio para que respire y pincélala con el otro huevo batido.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 8, 'Hornea hasta que la tapa esté dorada y firme al golpearla.', 35, 200, null, null, null);
