  -- Fritos de pollo al sésamo y almendras
  v_v := pg_temp.receta('Fritos de pollo al sésamo y almendras', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 40, 'Cubos de pechuga apanados en sésamo y almendra molida y fritos hasta que la costra queda crocante y perfumada. Se comen con ensalada verde y limón, y funcionan igual de bien como plato de fondo o para picar.');
  s := pg_temp.slot(v_v, 'PROTEIN', 1, null, true);
  perform pg_temp.comp(s, 'pechuga de pollo sin piel', 'RAW', 700, 'G', 'FRIED', false, 1, null, 'MAIN', 'ADJUSTABLE', 500, 900, null, null, null);
