  perform pg_temp.comp(s, 'harina de trigo', 'RAW', 50, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 35, 60, 'se declara la que queda pegada a los trozos; en el plato del apanado siempre sobra bastante más', null, null);
