  perform pg_temp.comp(s, 'almendras', 'AS_PACKAGED', 60, 'G', null, false, 4, null, 'MAIN', 'ADJUSTABLE', 40, 80, 'molidas a arenilla gruesa; hechas polvo se queman antes de que el pollo se cocine', null, null);
  perform pg_temp.alt(s, 'pan rallado', 'GOOD', 'mitad y mitad con el sésamo cuando no hay almendras; la costra queda menos perfumada y más neutra', null);
  s := pg_temp.slot(v_v, 'FAT', 3, null, true);
  perform pg_temp.comp(s, 'aceite vegetal', 'AS_PACKAGED', 60, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 40, 80, 'es el aceite que se queda en la costra. La sartén lleva mucho más y ese no se come', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 4, null, true);
  perform pg_temp.comp(s, 'limon', 'RAW', 40, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', null, null, null, null, null);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 5, 'G', null, false, 2, null, 'SEASONING', 'ADJUSTABLE', 0, 6, null, null, null);
  s := pg_temp.slot(v_v, 'SALAD', 5, null, true);
  perform pg_temp.comp_anidada(s, 'Ensalada verde', 1, 1);
  perform pg_temp.paso(v_v, 1, 'Corta la pechuga en cubos de unos tres centímetros, sálalos y rocíalos con el jugo de limón.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Pica las almendras hasta dejarlas como arenilla gruesa y mézclalas con el sésamo en un plato hondo.', 5, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'En vez de picarlas a cuchillo: dale tres golpes cortos a las almendras en la procesadora, hasta que queden con grano. Si te pasas se hacen pasta y ya no apanan.', 1, null, 'FOOD_PROCESSOR', 'Sin procesadora: pícalas a cuchillo como en el paso anterior, o machácalas dentro de una bolsa con el uslero.', null);
  perform pg_temp.paso(v_v, 4, 'Pasa cada cubo por harina, después por huevo batido y al final apriétalo contra la mezcla de sésamo y almendras para que se pegue bien.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Fríelos en aceite caliente, por tandas y sin amontonar, hasta que estén dorados por fuera y sin nada rosado al centro. En la sartén va bastante más aceite del que declara la receta: ese se queda en la sartén, no en el plato.', 12, null, null, null, null);
  perform pg_temp.paso(v_v, 6, 'En vez de freír en la sartén: pincela los cubos con un poco de aceite y dóralos en la air fryer, dándolos vuelta a la mitad.', 14, 190, 'AIR_FRYER', 'Sin air fryer: la sartén con aceite del paso anterior es el método base de esta receta.', null);
  perform pg_temp.paso(v_v, 7, 'Escúrrelos sobre papel, sálalos apenas y sírvelos con la ensalada verde y más limón.', 3, null, null, null, null);
