  perform pg_temp.paso(v_v, 1, 'Bate la harina con los huevos, la leche y una pizca de sal hasta que quede un batido liviano y sin grumos; déjalo reposar mientras preparas el relleno.', 10, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'En vez de batir a mano: junta la harina, los huevos, la leche y la sal en la licuadora y dale medio minuto.', 2, null, 'BLENDER', 'Sin licuadora: el batidor de mano del paso anterior sirve igual; cierne la harina antes para que no queden grumos.', null);
  perform pg_temp.paso(v_v, 3, 'Cuece la zanahoria rallada y las arvejas en poca agua con sal hasta que estén tiernas y escúrrelas bien.', 10, null, null, null, 1);
