  s := pg_temp.slot(v_v, 'VEGETABLE', 5, null, true);
  perform pg_temp.comp(s, 'choclo en grano', 'RAW', 400, 'G', 'STEWED', false, 1, null, 'MAIN', 'ADJUSTABLE', 300, 500, null, null, null);
  s := pg_temp.slot(v_v, 'SAUCE', 6, null, true);
