  perform pg_temp.alt(s, 'leche liquida entera', 'GOOD', 'con una cucharadita de harina para que espese; el choclo queda menos untuoso', 1);
  s := pg_temp.slot(v_v, 'FAT', 7, null, true);
  perform pg_temp.comp(s, 'mantequilla', 'AS_PACKAGED', 20, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 10, 30, 'para saltear el choclo antes de la crema', null, null);
  perform pg_temp.comp(s, 'aceite vegetal', 'AS_PACKAGED', 70, 'ML', null, false, 2, null, 'ADDED_FAT', 'ADJUSTABLE', 50, 90, 'el retenido por el apanado y el plátano. La sartén lleva bastante más y ese aceite se queda en la sartén', null, null);
