  perform pg_temp.paso(v_v, 3, 'Blanquea las mitades ahuecadas dos o tres minutos en agua hirviendo con sal y déjalas boca abajo sobre un paño para que escurran.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Sofríe la cebolla y el ajo con el aceite, el comino y el ají de color; suma la carne molida y la pulpa picada y cocina hasta que se seque el jugo.', 12, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Agrega el tomate y el orégano, deja espesar y sala. Cuando el relleno esté tibio, lígalo con el huevo batido.', 8, null, null, null, null);
