  -- Masa de empanadas al horno
  v_v := pg_temp.receta('Masa de empanadas al horno', 'MEAL', array['OTHER']::public.meal_type[], 4, 65, 'La masa de empanada de horno como se hace en casa: harina, manteca derretida en agua caliente y vino blanco, sin polvos de hornear. Es un componente, no un plato: con esta tanda salen unos doce discos para rellenar con lo que haya.');
  s := pg_temp.slot(v_v, 'BASE', 1, null, true);
  perform pg_temp.comp(s, 'harina de trigo', 'RAW', 750, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 600, 900, 'con 750 g salen unos doce discos de quince centímetros, es decir tres empanadas por porción', null, null);
  perform pg_temp.comp(s, 'vino blanco', 'AS_PACKAGED', 80, 'ML', null, false, 2, null, 'MAIN', 'ADJUSTABLE', 50, 100, 'va en la masa, no en el pino: le da elasticidad y ese gusto que la marca como masa de empanada', null, null);
  s := pg_temp.slot(v_v, 'FAT', 2, null, true);
  perform pg_temp.comp(s, 'manteca de cerdo', 'AS_PACKAGED', 150, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 120, 180, 'derretida en el agua caliente; es ella la que da la textura, no un leudante, y por eso no se puede sacar', null, null);
  perform pg_temp.alt(s, 'mantequilla', 'GOOD', 'sabor más lácteo y masa algo menos crocante que con manteca', 1);
  s := pg_temp.slot(v_v, 'TOPPING', 3, null, false);
  perform pg_temp.comp(s, 'huevo de gallina', 'EDIBLE_PORTION', 55, 'G', null, true, 1, null, 'MAIN', 'OPTIONAL', null, null, 'batido, solo para pintar los discos antes del horno', 'unidad', 1);
  s := pg_temp.slot(v_v, 'OTHER', 4, null, true);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 12, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', 6, 15, null, null, null);
  perform pg_temp.paso(v_v, 1, 'Cierne la harina con la sal sobre el mesón y hazle un hoyo grande al centro.', 5, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Derrite la manteca en unos 250 ml de agua bien caliente hasta que quede una sola cosa; no la dejes hervir.', 5, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Vuelca ese líquido tibio y el vino blanco dentro del hoyo y ve juntando la harina desde afuera hacia adentro con la mano.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Amasa hasta que quede lisa y elástica, sin migas sueltas. Si se pega, un poco más de harina; si se quiebra, unas gotas de agua tibia.', 12, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Tápala y déjala descansar a temperatura ambiente. Sin ese descanso la masa se retrae al estirarla y la empanada sale dura.', 20, null, null, null, null);
  perform pg_temp.paso(v_v, 6, 'Estírala de a poco hasta dejarla de unos tres milímetros y corta discos de unos quince centímetros. No lleva polvos de hornear a propósito: el hojaldrado lo da la manteca.', 15, null, null, null, null);
  perform pg_temp.publicar(v_v);

