  -- Spaghetti mediterráneo
  v_v := pg_temp.receta('Spaghetti mediterráneo', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 37, 'Tomate crudo picado que se marina con ajo, albahaca, aceitunas y aceite de oliva, y que se cocina solo con el calor de los fideos recién colados. El tomate nunca ve el fuego: por eso queda fresco y no sabe a salsa.');
