  perform pg_temp.comp(s, 'ajo', 'RAW', 8, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', 4, 15, 'muy picado y crudo; poco, porque no se cocina', null, null);
  perform pg_temp.comp(s, 'albahaca fresca', 'RAW', 20, 'G', null, false, 2, null, 'SEASONING', 'ADJUSTABLE', 10, 30, 'rasgada con la mano; el cuchillo la ennegrece', null, null);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 10, 'G', null, false, 3, null, 'SEASONING', 'ADJUSTABLE', 5, 14, null, null, null);
