  perform pg_temp.comp(s, 'queso mantecoso', 'AS_PACKAGED', 80, 'G', null, true, 1, null, 'MAIN', 'OPTIONAL', 0, 120, null, null, null);
  perform pg_temp.alt(s, 'quesillo', 'GOOD', 'desmenuzado encima y frio; con el tomate crudo funciona mejor que el mantecoso derretido', 1);
  perform pg_temp.paso(v_v, 1, 'Pica el tomate en cubos de centímetro y medio, con piel y con su jugo, y ponlo en el bol grande donde vas a servir. Suma el ajo muy picado, las aceitunas en rodajas, la albahaca rasgada, el aceite de oliva y sal, revuelve y déjalo ahí: esa marinada es toda la cocción que va a tener el tomate.', 12, null, null, null, 1);
  perform pg_temp.paso(v_v, 2, 'Mientras el tomate se marina, pon a hervir una olla grande con harta agua y sal.', 10, null, null, null, 1);
  perform pg_temp.paso(v_v, 3, 'Cuece los fideos al dente y cuelalos guardando media taza del agua.', 10, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Échalos hirviendo sobre el tomate crudo y revuelve fuerte: el calor de los fideos entibia el tomate y suelta el aceite. Si queda seco, agrega un chorro del agua de cocción.', 3, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Sirve al tiro, con queso encima si quieres. Este plato no espera: recalentado el tomate se cocina y deja de ser lo que es.', 2, null, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Ravioles de ricotta en salsa de tomate fresco
  v_v := pg_temp.receta('Ravioles de ricotta en salsa de tomate fresco', 'MEAL', array['LUNCH', 'DINNER']::public.meal_type[], 4, 70, 'Ravioles hechos en casa con masa de huevo y relleno de ricotta con albahaca, en una salsa de tomate fresco de quince minutos. Si el día no da para amasar, con ravioles comprados la salsa igual sostiene el plato.');
