  perform pg_temp.comp(s, 'queso mantecoso', 'AS_PACKAGED', 60, 'G', null, true, 2, null, 'MAIN', 'OPTIONAL', 0, 100, 'rallado dentro del relleno, para que amarre', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 3, null, true);
