  perform pg_temp.alt(s, 'salsa de tomate envasada', 'ACCEPTABLE', 'fuera de temporada el tomate no sirve; envasada queda mas dulce y menos fresca, que es justo lo contrario de esta receta', 0.5);
  s := pg_temp.slot(v_v, 'FAT', 5, null, true);
