  -- Palmeritas
  v_v := pg_temp.receta('Palmeritas', 'DESSERT', array['TEA', 'SNACK', 'DESSERT']::public.meal_type[], 8, 51, 'Hojaldre enrollado con azucar y cortado en tajadas, que se caramela en el horno hasta quedar crujiente. Son tres ingredientes y media hora para llenar una bandeja de once.');
  s := pg_temp.slot(v_v, 'BASE', 1, null, true);
