  perform pg_temp.alt(s, 'harina de trigo', 'ACCEPTABLE', 'hojaldre rapido casero en vez del comprado: 250 g de harina, 250 g de mantequilla fria en cubos, 120 ml de agua helada y una cucharadita de sal. Junta sin deshacer la mantequilla y dale tres vueltas de doblez simple, con descanso en frio entre cada una.', 0.5);
  s := pg_temp.slot(v_v, 'SWEETENER', 2, null, true);
  perform pg_temp.comp(s, 'azucar granulada', 'AS_PACKAGED', 120, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 90, 150, 'es la cantidad que queda pegada al hojaldre y caramelada encima; lo que se salga a la lata no se come y por eso no se declara mas', null, null);
  s := pg_temp.slot(v_v, 'OTHER', 3, null, false);
  perform pg_temp.comp(s, 'canela molida', 'AS_PACKAGED', 3, 'G', null, true, 1, null, 'SEASONING', 'OPTIONAL', 0, 5, null, null, null);
  perform pg_temp.paso(v_v, 1, 'Estira el hojaldre en un rectangulo sobre la mesa espolvoreada con azucar, cúbrelo con el resto del azucar y la canela y pasa el uslero para que se peguen.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Enrolla los dos lados largos hasta que se junten al centro, aprieta el rollo y córtalo en tajadas de un centímetro.', 7, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Ponlas bien separadas en la lata con papel, en dos latas —se hinchan al doble y pegadas se sueltan—, con la cara cortada hacia arriba, y hornea; a la mitad dales vuelta para que el azucar caramele por los dos lados. Salen blandas y endurecen al enfriar.', 36, 200, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Picarones
  v_v := pg_temp.receta('Picarones', 'DESSERT', array['DESSERT', 'TEA', 'SNACK']::public.meal_type[], 6, 107, 'Ruedas de masa leudada con zapallo, fritas y bañadas en almíbar de chancaca con naranja y canela. Es el postre de fonda y de tarde de lluvia, y se come caliente.');
