  perform pg_temp.comp(s, 'aceite vegetal', 'AS_PACKAGED', 120, 'ML', null, false, 1, null, 'ADDED_FAT', 'ADJUSTABLE', 90, 150, 'aceite RETENIDO por los picarones, no el baño de la olla: la masa leudada absorbe bastante mas que una masa fina. En la olla van cerca de litro y medio y casi todo se queda ahí.', null, null);
  s := pg_temp.slot(v_v, 'SWEETENER', 4, null, true);
