  v_v := pg_temp.receta('Sémola con leche', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 25, 'Sémola cocida en leche con canela y cáscara de limón hasta que queda cremosa. Postre de olla barato, de los que se sirven tibios en pocillo después del almuerzo.');
