  v_v := pg_temp.receta('Leche nevada', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 32, 'Crema de leche y yemas con copos de merengue pochados encima, como islas flotando. Nada va al horno: todo se hace en la olla, y por eso queda más liviana que un flan.');
