  -- Macho ruso
  v_v := pg_temp.receta('Macho ruso', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 30, 'Postre de leche cuajado con maicena sobre una capa de caramelo, desmoldado como flan. No lleva huevo: la textura la da el almidón, y por eso queda más sedosa y menos firme.');
  s := pg_temp.slot(v_v, 'BASE', 1, null, true);
  perform pg_temp.comp(s, 'leche liquida entera', 'AS_PACKAGED', 1000, 'ML', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 900, 1100, null, null, null);
  perform pg_temp.comp(s, 'maicena', 'AS_PACKAGED', 90, 'G', null, false, 2, null, 'MAIN', 'ADJUSTABLE', 80, 100, 'es lo único que cuaja este postre: no lleva huevo, así que bajar la maicena significa que no se sostiene al desmoldar', null, null);
  s := pg_temp.slot(v_v, 'SWEETENER', 2, null, true);
