  -- Cocadas
  v_v := pg_temp.receta('Cocadas', 'DESSERT', array['DESSERT', 'TEA', 'SNACK']::public.meal_type[], 6, 43, 'Montoncitos de coco rallado unidos con huevo y azúcar, horneados hasta quedar dorados por fuera y blandos por dentro. Se hacen en una tanda grande y desaparecen en la once.');
