  -- Calugas caseras
  v_v := pg_temp.receta('Calugas caseras', 'DESSERT', array['DESSERT', 'SNACK', 'TEA']::public.meal_type[], 6, 45, 'Caramelos blandos de leche, azúcar y mantequilla cocidos hasta punto de bola blanda y cortados en cuadraditos. Es el dulce de olla de toda la vida, y cuesta más la paciencia que los ingredientes.');
