  perform pg_temp.paso(v_v, 3, 'Revuelve las galletas molidas con la mantequilla derretida y apriétalas con el fondo de un vaso en la base de un molde desmontable. Déjalo en el refrigerador mientras haces el relleno.', 7, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Hidrata la gelatina en 60 ml de agua fría hasta que se hinche y disuélvela a baño maría suave, revolviendo. No la hiervas: hervida pierde fuerza y la torta no cuaja.', 5, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'En vez del baño maría: dale veinte segundos de microondas y revuelve, repitiendo de a diez segundos hasta que quede transparente, sin dejar que hierva.', 1, null, 'MICROWAVE', 'Sin microondas: el baño maría suave del paso anterior, que es el método base de esta receta.', null);
  perform pg_temp.paso(v_v, 6, 'Bate el yogur con el azúcar y la ralladura de limón y agrégale la gelatina tibia en hilo, revolviendo sin parar. Si la echas de una vez y fría, se hacen hebras.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 7, 'Bate la crema fría hasta que sostenga forma y envuélvela con la mezcla de yogur, con espátula y de abajo hacia arriba.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 8, 'Vierte sobre la base, empareja y déjala en el refrigerador hasta que esté firme al tacto en el centro. Recién ahí cúbrela con la mermelada y desmóldala.', null, null, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Merengón con berries
  v_v := pg_temp.receta('Merengón con berries', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 8, 111, 'Un merengue grande secado al horno, crocante por fuera y blando adentro, con crema batida y berries frescos encima. Se arma en la mesa y se sirve al tiro, con azúcar granulada de toda la vida.');
  s := pg_temp.slot(v_v, 'BASE', 1, null, true);
