  v_v := pg_temp.receta('Tarta de manzana', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 8, 89, 'Masa de mantequilla forrando el molde y manzana en láminas delgadas montadas encima, horneada hasta que las puntas se tuestan. Es el postre que sale con manzanas que ya están pasadas de punto para comerlas crudas.');
  s := pg_temp.slot(v_v, 'BASE', 1, null, true);
