  perform pg_temp.comp(s, 'huevo de gallina', 'EDIBLE_PORTION', 55, 'G', 'BAKED', false, 3, null, 'MAIN', 'FIXED', null, null, 'la yema junta la masa y con la clara batida se pinta el borde para que dore parejo', 'unidad', 1);
