  perform pg_temp.comp(s, 'limon', 'RAW', 40, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', 0, 60, 'el jugo sobre la manzana recién cortada, para que no se ponga oscura mientras armas', null, null);
  perform pg_temp.comp(s, 'canela molida', 'AS_PACKAGED', 3, 'G', null, true, 2, null, 'SEASONING', 'OPTIONAL', null, null, null, null, null);
  perform pg_temp.comp(s, 'sal', 'AS_PACKAGED', 1, 'G', null, false, 3, null, 'SEASONING', 'ADJUSTABLE', 0, 2, null, null, null);
  s := pg_temp.slot(v_v, 'TOPPING', 5, null, false);
  perform pg_temp.comp(s, 'mermelada', 'AS_PACKAGED', 60, 'G', null, true, 1, null, 'MAIN', 'OPTIONAL', 0, 90, 'de damasco, derretida con un chorrito de agua y pincelada al final: es todo el brillo de la tarta', null, null);
  perform pg_temp.alt(s, 'azucar flor', 'GOOD', 'en vez del brillo de mermelada, espolvoreada sobre la tarta ya fría; se ve más rústica y hay que poner mucho menos peso', 0.4);
  perform pg_temp.paso(v_v, 1, 'Arena la mantequilla fría con la harina, 40 g del azúcar y la sal hasta formar migas. Junta la masa con la yema y una o dos cucharadas de agua helada y déjala descansar fría.', 15, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Pela las manzanas, sácales el centro y córtalas en láminas delgadas. Rocíalas con el jugo de limón y revuélvelas con el azúcar que queda y la canela.', 10, null, null, null, null);
  perform pg_temp.paso(v_v, 3, 'Estira la masa y forra un molde de 26 cm dejando un borde alto. Pincha el fondo con un tenedor.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Acomoda las láminas de manzana en círculos, montadas una sobre otra. Aprieta más de lo que te parece necesario: en el horno se bajan bastante y si las pones sueltas la tarta queda flaca.', 8, null, null, null, null);
  perform pg_temp.paso(v_v, 5, 'Pinta el borde con la clara batida y hornea a 190 °C hasta que la masa esté dorada por debajo y las puntas de la manzana empiecen a tostarse.', 45, 190, null, null, null);
  perform pg_temp.paso(v_v, 6, 'Derrite la mermelada con un chorrito de agua y pincela la tarta todavía caliente. Déjala enfriar sobre una rejilla para que el fondo no se humedezca con su propio vapor.', 5, null, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Tarta de duraznos y limón
  v_v := pg_temp.receta('Tarta de duraznos y limón', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 8, 67, 'Masa horneada en blanco rellena con crema pastelera hecha en la olla, perfumada con ralladura de limón, y mitades de durazno en conserva encima. Es una tarta de vitrina que en la casa sale sin nada raro: leche, huevo, maicena y un tarro de duraznos.');
