  s := pg_temp.slot(v_v, 'SWEETENER', 2, null, true);
  perform pg_temp.comp(s, 'azucar granulada', 'AS_PACKAGED', 150, 'G', 'BAKED', false, 1, null, 'MAIN', 'ADJUSTABLE', 120, 180, '50 g en la masa y 100 g en la crema pastelera', null, null);
