  perform pg_temp.comp(s, 'maicena', 'AS_PACKAGED', 45, 'G', 'BOILED', false, 3, null, 'MAIN', 'ADJUSTABLE', 40, 55, 'es lo que sostiene la crema al cortar la porción; con menos, la tarta se desparrama en el plato', null, null);
  s := pg_temp.slot(v_v, 'FRUIT', 4, null, true);
  perform pg_temp.comp(s, 'duraznos en conserva', 'DRAINED', 500, 'G', 'RAW', false, 1, null, 'MAIN', 'ADJUSTABLE', 400, 600, 'peso ya escurrido; el almíbar se guarda aparte para pincelar al final', null, null);
  perform pg_temp.alt(s, 'arandanos', 'GOOD', 'crudos y repartidos sobre la crema ya fría; pesan la mitad porque cubren la superficie sin apilarse como las mitades de durazno', 0.5);
