  perform pg_temp.paso(v_v, 1, 'Arena 100 g de mantequilla fría con la harina, 50 g del azúcar y la sal, junta la masa con un poco de agua helada y déjala descansar fría.', 15, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'Estírala, forra el molde, pínchala y hornéala en blanco a 180 °C con papel y peso encima hasta que esté dorada y seca. Déjala enfriar en el molde.', 25, 180, null, null, 1);
  perform pg_temp.paso(v_v, 3, 'Mientras la masa está en el horno, calienta la leche con la ralladura de limón hasta que largue vapor, sin dejarla hervir.', 8, null, null, null, 1);
