  s := pg_temp.slot(v_v, 'DESSERT_COMPONENT', 2, null, true);
  perform pg_temp.comp(s, 'helado de vainilla', 'AS_PACKAGED', 300, 'G', 'RAW', false, 1, null, 'MAIN', 'ADJUSTABLE', 200, 400, 'unas tres bolas por copa', null, null);
