  perform pg_temp.comp(s, 'leche liquida entera', 'AS_PACKAGED', 30, 'ML', null, false, 2, null, 'MAIN', 'ADJUSTABLE', 20, 50, 'es lo que deja la salsa fluida; sin ella el chocolate se endurece al tocar el helado', null, null);
  perform pg_temp.alt(s, 'manjar', 'EXCELLENT', 'manjar aflojado con leche tibia en vez de la salsa de chocolate; hay que poner más porque es menos intenso y se reparte más grueso', 1.5);
  s := pg_temp.slot(v_v, 'TOPPING', 4, null, true);
