  perform pg_temp.comp(s, 'azucar flor', 'AS_PACKAGED', 25, 'G', null, false, 1, null, 'MAIN', 'ADJUSTABLE', 0, 40, 'para la crema; el manjar ya pone todo el dulce del postre', null, null);
