  perform pg_temp.comp(s, 'limon', 'RAW', 20, 'G', null, false, 1, null, 'SEASONING', 'ADJUSTABLE', 0, 30, 'unas gotas sobre el plátano cortado para que no se ponga oscuro mientras armas', null, null);
  perform pg_temp.paso(v_v, 1, 'Muele las galletas hasta dejarlas como arena gruesa. Si no tienes máquina, mételas en una bolsa y pásales el uslero o una botella por encima.', 6, null, null, null, null);
  perform pg_temp.paso(v_v, 2, 'En vez de molerlas a mano: pasa las galletas por la procesadora en pulsos cortos hasta dejarlas como arena gruesa.', 2, null, 'FOOD_PROCESSOR', 'Molerlas dentro de una bolsa con un uslero o una botella, como dice el paso anterior.', null);
  perform pg_temp.paso(v_v, 3, 'Mezcla las galletas molidas con la mantequilla derretida hasta que se vea como arena mojada y apriétala fuerte contra el fondo de un molde desmontable con el revés de una cuchara.', 7, null, null, null, null);
  perform pg_temp.paso(v_v, 4, 'Lleva el molde al congelador mientras sigues: la base se afirma en minutos y así el manjar no la levanta al extenderlo.', 10, null, null, null, 1);
  perform pg_temp.paso(v_v, 5, 'Mientras la base se afirma, bate la crema bien fría con el azúcar flor hasta que quede firme.', 8, null, null, null, 1);
  perform pg_temp.paso(v_v, 6, 'Extiende el manjar sobre la base fría, corta el plátano en rodajas, rocíalo con unas gotas de limón y acomódalo cubriendo todo. Tápalo con la crema batida y espolvorea el cacao.', 7, null, null, null, null);
  perform pg_temp.paso(v_v, 7, 'Corta con un cuchillo grande y firme, apretando derecho hacia abajo: si lo mueves como sierra, las rodajas de plátano se resbalan y la porción se desarma.', 3, null, null, null, null);
  perform pg_temp.publicar(v_v);

  -- Selva negra
  v_v := pg_temp.receta('Selva negra', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 10, 104, 'Torta de bizcocho de cacao en tres discos, mojados con almíbar de guindas y armados con crema batida, guindas y virutas de chocolate. Es de ocasión y toma su tiempo, pero no necesita nada que no se consiga en el supermercado.');
