  perform pg_temp.comp(s, 'huevo de gallina', 'EDIBLE_PORTION', 330, 'G', 'BAKED', false, 3, null, 'MAIN', 'ADJUSTABLE', 275, 330, 'van enteros y batidos largo rato: son lo único que levanta este bizcocho', 'unidad', 6);
  perform pg_temp.comp(s, 'mantequilla', 'AS_PACKAGED', 120, 'G', 'BAKED', false, 4, null, 'MAIN', 'ADJUSTABLE', 100, 140, 'derretida y tibia; caliente baja el batido de los huevos de golpe', null, null);
