  perform pg_temp.comp(s, 'azucar granulada', 'AS_PACKAGED', 300, 'G', 'BAKED', false, 1, null, 'MAIN', 'ADJUSTABLE', 250, 350, '200 g al bizcocho y los 100 g restantes repartidos entre el almíbar y la crema', null, null);
  perform pg_temp.alt(s, 'azucar flor', 'GOOD', 'solo para la parte de la crema, donde se disuelve sin dejar grano; el bizcocho necesita la granulada', 1);
