  perform pg_temp.comp(s, 'crema para batir', 'AS_PACKAGED', 700, 'ML', 'RAW', false, 1, null, 'MAIN', 'ADJUSTABLE', 600, 800, 'es el relleno y la cobertura entera; muy fría o no monta y se te corta al seguir batiendo', null, null);
  s := pg_temp.slot(v_v, 'FRUIT', 4, null, true);
