  perform pg_temp.alt(s, 'arandanos', 'ACCEPTABLE', 'frescos y sin almíbar: hay que mojar el bizcocho con otra cosa y la torta pierde la acidez de la guinda, que es lo que la sostiene contra tanta crema', 0.7);
  s := pg_temp.slot(v_v, 'TOPPING', 5, null, true);
