  -- Macarrones franceses
  v_v := pg_temp.receta('Macarrones franceses', 'DESSERT', array['DESSERT', 'TEA']::public.meal_type[], 6, 108, 'Conchas de harina de almendras y merengue, secadas al aire antes de hornear para que salga el pie, unidas de a dos con ganache de chocolate. Es la receta más exigente del recetario: el punto de cinta y el reposo antes del horno no se pueden apurar.');
